fn determine_winner(x: i8, y: i8) -> &'static str {
    // Compute the absolute difference
    let diff = (x - y).abs();
    // If the difference is strictly greater than 1, Alice wins; otherwise Brown wins.
    if diff > 1 {
        "Alice"
    } else {
        "Brown"
    }
}

fn main() {
    // Some tests
    assert_eq!(determine_winner(0, 0), "Brown"); // diff = 0
    assert_eq!(determine_winner(1, 0), "Brown"); // diff = 1
    assert_eq!(determine_winner(2, 0), "Alice"); // diff = 2
    assert_eq!(determine_winner(5, 3), "Brown"); // diff = 2
    assert_eq!(determine_winner(10, 8), "Alice"); // diff = 2
    assert_eq!(determine_winner(7, 6), "Brown");  // diff = 1

    println!("All tests passed!");
}